"""Prepare fifteen independent reference-based concept briefs; no image processing."""
from pathlib import Path
import json,hashlib
ROOT=Path(__file__).resolve().parents[2];V=ROOT/'design'
campaign=json.loads((ROOT/'research/city-campaign.json').read_text(encoding='utf-8'))
scenes={
'BRY':('A wealthy busy free trading port city quarter, cream stone and dark timber houses, rust-red and brown roof tiles, broad stone market visibly connected to cramped rental alley, dock rope winches and floodgate canal, an artisan courtyard. Three local viewpoints, tenants, workers and merchants share a modest evening negotiation hall, no castle monument. Ordinary inhabitants, goods limited, a closed gate with a clear side walking lane.','golden ochre, faded brick red, slate water','020','083'),
'ALD':('An inhabited craft city quarter, old stone streets and modest religious courtyards separated by everyday living spaces. Skilled armour and goldworkers display a well-made breastplate while an apprentice with a bandaged hand works by a separate lining bench, exterior and a small roofless workshop reveal. Distinct metalwork display frontage and unglamorous labour/back courtyard. No royal palace, no royal family portraits, no modern ruined siege claim.','aged brass, stone grey, muted red cloth','020','099'),
'MAE':('Cold war-damaged inhabited city quarter, damaged scholarly archive outer court and partially roofless record shelter, ruined weaving street still sheltering people, small root-vegetable kitchen, separated anonymous care beds and private record cabinets, a clearly open exit lane. Three different groups of surviving residents, tiny warm windows amid grey walls. Archive remains damaged, no thriving restored academy, no large purple magic city.','cold blue-grey, dark timber, scarce warm amber','088','060'),
'DEN':('A damaged coastal fishing village quarter, broken pale salt-stained masonry and wood piles, original fishing homes and a separate modest garrison-side street, nets, small tidal landing, two visibly habitable repaired rooms and an unresolved roofless third home. Three families discuss repairs around a safe high bank, no grand harbour or large castle.','salt grey, sea slate, dull red net floats','088','083'),
'OSB':('An inland agricultural village outer yard with low thatch and half-timber homes, small grain shed, abandoned mill side yard and creek bridge, short muddy paths between households, yellow field edges. A mother, her daughter and mill renter examine finite seed grain by a separate household bowl. Peaceful country place, war has not devastated this village, no huge city walls.','wheat ochre, earth brown, muted olive','099','060'),
'MNS':('A war-damaged wine-producing small town outer quarter, terraced grape trellises with broken posts and new young vines, weathered low stone walls, shared cellar shown in a small roofless cutaway, repair workshop and little wine selling yard. Master and apprentice examine old seals and a new batch, distinct old/new marks on plain barrels without readable writing.','dusty purple grapes, grey limestone, brown timber','083','099'),
'SKO':('A modest inhabited smelting and forging town quarter, soot-dark brick sheds, furnace exterior and visible cooling water trench, charcoal stores, a finite ingot market and a small ransom deposit cabinet. A returning worker stands freely outside his old workshop, accountant and family nearby; washing hangs next to workshops. No massive industrial factory or infinite armoury.','soot grey, dark brick, restrained furnace orange','099','020'),
'YOS':('A wool-working small town quarter with narrow loom houses, wool sorting tables, hanging drying cloth in narrow muted colour strips, sheep-wool bundles, modest tent material racks and two separate maker benches. Master and departing apprentice both have visible distinct workspaces, cold wind bends drying fabric. Wool not flax, no axes military camp.','cream fleece, dull indigo, faded madder red','099','060'),
'KOR':('An entirely original modest urban residential quarter proposed for the little-known location Kord, small enclosed baggage-deposit courtyard, temporary lodgings with two different ordinary door markers, neutral witness booth and a side gate always open. Two unrelated households with similar names claim different stored objects; records and dwelling access separated. No royal palace, no mines, no sea harbour, no implied canonical geography or industry.','warm timber brown, plain limewash, subdued teal','099','020'),
'EED':('A woodland village quarter at a visible forest edge, modest saw frames, covered bow-stave shed, a river-side stack of numbered old cut beams, forest watch hut outside the home lane. Villagers keep private homes closed while meeting at the public material yard; an ordinary timber order contends with local bridge repair. No grand militia headquarters, no mass logging wasteland.','moss olive, seasoned timber, grey water','060','099'),
'FOR':('A gold-mining small town outer quarter, rough low timber pit entrance, surface airshaft and bracing inspection courtyard, coarse ore weighing yard, miners families and a modest historic keepsake cabinet. A closed dangerous pit has an alternate safe daylight walkway; workers and a ventilation maintainer can stop work. More dull ore and dirt than bright gold, no prison quarry, no huge golden bank.','raw stone grey, umber ore, tiny amber mine lamps','099','060'),
'RAT':('A rural small town quarter around a modest old memorial slope, ordinary surviving family courtyards, livestock enclosure and repair booth. Historic beast is dead: show weathered memorial relief only, no living huge monster. New ordinary tracks and a human-made rope noisemaker at fence indicate current separate threats; people discuss omitted family names near a small side memorial.','faded pasture green, weathered stone, russet roofs','060','099'),
'PAS':('An original basalt border pass and inhabited unloading village, dark rough stone low gate, a long unloading axis, grain weighing scales, crowded civilian carts and a safe pedestrian bypass separate from official checkpoint. Two separate civil/military records stations and ordinary household meals. Soldiers local and few, no royal capital or huge fortress army.','dark basalt, dry ochre, muted cloth blue','020','099'),
'ASH':('An original cold marsh basin care village, cold still water with reeds and raised dry footpaths, low care shelters with separately coloured buckets and curtains, actual inhabitants staying voluntarily and another safe path to leave. One modest communal care kitchen and independent medicine/observation tables visibly separated, no tropical plants, no monstrous patients.','cold reed green, ash grey, tiny hearth amber','060','088'),
'HIG':('An original wind-weathered cold highland monastery outer settlement distinct from game prologue, rough rock terraces, old bell scaffold, sheltered maintainer quarters, one closed unsafe bridge section and visibly open outer return walk. Small calibration stand with ordinary mechanical readings; extremely scarce dim purple mineral light below one sealed grille, no giant glowing crystals or restored cathedral.','wind slate, dead wood brown, very sparse dim violet','060','099')}
base='''Use case: stylized-concept. Asset type: reference-based city and satellite settlement concept board for the Stoneshard mod Embers and Oaths, an art-direction draft, not an engine screenshot.
Input image 1 and input image 2 are original game atlas pages provided by the user. Read only their building silhouettes, hard pixel clusters, steep roofs, material vocabulary, terrain details and orthographic camera. Invent a new inhabited layout; do not replicate the atlas arrangement or copy original character portraits, UI, glyphs, flags or logos. Ignore atlas black/white packing voids, unfinished fragments and duplicate animation frames.
Style: crisp deliberately hand-pixelled 2D medieval RPG environmental art, square-grid streets and ground, top-down oblique orthographic view with visible front facades matching reference sprites, NOT a cinematic realistic painting, NOT diamond-grid isometric, NOT smooth 3D render. Compact 30-to-40-pixel-like inhabitants relative to buildings, strong legible doors and paths, restrained low-saturation palette, hard outlines and limited shading ramps, consistent scale.
Composition: one landscape board, main city/region scene occupies upper 65%, lower strip has {count} clearly separated SMALL satellite vignettes with much smaller population and building count, one per settlement listed below in left-to-right order. Modest thin parchment dividers, no decorative art frame. Within the main scene doors and walking lanes are clear; an alternate return path stays visible. Do not make a city or village a giant dollhouse island. Include subtle action and inhabitants associated with the stated local story, not a title banner covering streets.
Main scene: {scene}
Palette: {palette}.
Satellite strip:
{satellites}
Text: only tiny clean panel identifiers "{cid}", {labels}; no other written text. Place identifiers in narrow divider margins, not floating over gameplay spaces. Chinese settlement names and exact quest links will be in the companion Markdown.
Constraints: locality and civil-scale everyday lives, no new royal genealogy, no invented global territory claims, no nationwide army headquarters, no spectacular anachronistic technology. Keep all satellite scenes mutually distinct in architecture placement and human conflict, not repeats of the same three huts. Opaque background. This is visual research derived from references, not exported commercial sprites or ready-to-load textures.'''
briefs=[]
for c in campaign['cities']:
 scene,palette,a,b=scenes[c['id']];ss=c['satellites']
 descriptions=[]
 for i,s in enumerate(ss,1):
  descriptions.append(f"{s['id']}: {s['name']} ({s['function']}); local tension {s['dilemma']}. Show a public arrival path, modest everyday service shelter and a local story meeting place. Use parent region climate/materials but a separate small settlement layout.")
 prompt=base.format(count=len(ss),scene=scene,palette=palette,satellites='\n'.join(descriptions),cid=c['id'],labels=', '.join('"'+s['id']+'"' for s in ss))
 refs=[ROOT/f'stoneshard-assets-sample/atlas-{x}.png' for x in [a,b]]
 briefs.append(dict(id=c['id'],name=c['name'],prompt=prompt,reference_paths=[str(p) for p in refs],
   reference_hashes={p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in refs},
   output=f"design/12_美术参考/城市概念/{c['id']}-概念-v1.png",city_note='design/'+c['file'],
   satellite_notes=['design/'+s['file'] for s in ss],main_quest=c['main_id'],status='prepared'))
p=ROOT/'research/city-art-briefs.json'
if p.exists():raise SystemExit('Existing art briefs must be preserved/reconciled before changing prompts.')
p.write_text(json.dumps(dict(date='2026-10-12',tool='built-in image_gen',use_case='stylized-concept',briefs=briefs),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(json.dumps(dict(briefs=len(briefs),satellite_vignettes=sum(len(c['satellites']) for c in campaign['cities'])),ensure_ascii=False))
